<template><view class="page"><view class="top"><text class="back" @tap="back">‹</text><text class="title">预约到店</text><text class="blank"></text></view><view class="hero"><text class="h">安排一次专属参观</text><text class="s">手机号已由账号验证，只需选择日期和时间</text></view><view class="card"><picker mode="date" :value="date" :start="today" @change="date=$event.detail.value"><view class="field"><text>到店日期</text><text>{{date||'请选择'}} ›</text></view></picker><picker :range="slots" :value="slotIndex" @change="slotIndex=Number($event.detail.value)"><view class="field"><text>到店时间</text><text>{{slots[slotIndex]}} ›</text></view></picker><view class="field"><text>意向内容</text><input v-model.trim="intent" maxlength="80" placeholder="房型、护理或产康（选填）" /></view><button class="submit" :loading="submitting" @tap="submit">提交预约</button></view></view></template>
<script>import{makeApi,REMOTE}from'@/common/remote.js';export default{data(){const d=new Date();return{today:d.toISOString().slice(0,10),date:'',slots:['09:00-11:00','14:00-16:00','16:00-18:00'],slotIndex:0,intent:'',submitting:false}},methods:{back(){uni.navigateBack()},async submit(){if(!this.date)return uni.showToast({title:'请选择到店日期',icon:'none'});this.submitting=true;try{const start=this.slots[this.slotIndex].slice(0,5);await makeApi().createAppointment({customerId:REMOTE.customerId,project:'到店参观'+(this.intent?' · '+this.intent:''),time:this.date+'T'+start+':00',status:'待接单'});uni.showModal({title:'预约已提交',content:'顾问确认后，您可以在“我的月子”中查看预约状态。',showCancel:false,success:()=>uni.switchTab({url:'/pages/home/home'})})}catch(e){uni.showToast({title:e.message||'预约失败',icon:'none'})}finally{this.submitting=false}}}}</script>
<style lang="scss" scoped>.page{min-height:100vh;background:linear-gradient(160deg,$ivory,#EEECE7)}.top{padding:calc(env(safe-area-inset-top) + 20rpx) 34rpx 12rpx;display:flex;justify-content:space-between;align-items:center}.back,.blank{width:60rpx}.back{font-size:52rpx;color:$gold-deep}.title{font-family:$font-cn-serif;font-size:31rpx}.hero{padding:64rpx 40rpx 36rpx;text-align:center}.h{display:block;font-family:$font-cn-serif;font-size:42rpx}.s{display:block;color:$ink-3;font-size:23rpx;margin-top:8rpx}.card{margin:20rpx 34rpx;background:rgba(255,255,255,.96);border:1rpx solid $hair;border-radius:34rpx;padding:32rpx;box-shadow:$shadow-soft}.field{min-height:80rpx;border-bottom:1rpx solid $hair;display:flex;align-items:center;justify-content:space-between;padding:10rpx 0;color:$ink-2}.field input{text-align:right;font-size:25rpx}.submit{margin-top:38rpx;height:90rpx;line-height:90rpx;border:0;border-radius:28rpx;background:$foil;color:#fff}.submit::after{border:0}</style>
